import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S07/S07E14.html","title":"S07E14 The One Where They All Turn Thirty","lang":"zh-CN","frontmatter":{"title":"S07E14 The One Where They All Turn Thirty","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":160},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":38.06,"words":11418},"filePathRelative":"语言/英语/Friends老友记/S07/S07E14.md"}`),l={name:`S07E14.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=a(`h1`,{id:`the-one-where-they-all-turn-thirty`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#the-one-where-they-all-turn-thirty`},[a(`span`,null,`The One Where They All Turn Thirty`)])],-1),c[1]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`他们都快三十岁了`)])],-1),c[2]||=a(`p`,null,`The One Where They All Turn Thirty`,-1),c[3]||=a(`blockquote`,null,[a(`p`,null,`他们都快三十岁了`)],-1),r(p,{src:`/audio/friends/S07/S07E14/001.mp3`}),c[4]||=i(),c[5]||=a(`strong`,null,`Teleplay by:`,-1),c[6]||=i(` Sherry Bilsing & Ellen Plummer`,-1),c[7]||=a(`blockquote`,null,[a(`p`,null,`雪莉·比尔辛和艾伦·普卢默`)],-1),r(p,{src:`/audio/friends/S07/S07E14/002.mp3`}),c[8]||=t(` <strong>Story by:</strong> Vanessa McCarthy<blockquote><p>凡妮莎·麦卡锡</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Joey and Rachel&#39;s, Joey is knocking on Rachel’s door, whose door frame is decorated with balloons. The rest of the gang is there as well. Rachel opens the door and the gang blow on noisemakers.</em></p><blockquote><p>🎬 <em>乔伊和瑞秋家，乔伊正在敲瑞秋家的门，瑞秋家的门框上装饰着气球。帮派的其他成员也在那里。瑞秋打开门，帮派向制造噪音的人吹气。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E14/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Ross Geller:`,-1),c[11]||=i(` Happy birthday!!!`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`生日快乐！！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Monica Geller:`,-1),c[15]||=i(` Happy birthday!!!`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`生日快乐！！！`)],-1),c[17]||=a(`p`,null,[a(`em`,null,`(Rachel glares at them and goes back into her room, closing her door.)`)],-1),c[18]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋瞪了他们一眼，然后回到她的房间，关上门。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/005.mp3`}),c[19]||=i(),c[20]||=a(`strong`,null,`All:`,-1),c[21]||=i(` Rach! Come on! Rach!`,-1),c[22]||=a(`blockquote`,null,[a(`p`,null,`瑞秋！来吧瑞秋！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/006.mp3`}),c[23]||=i(),c[24]||=a(`strong`,null,`Monica Geller:`,-1),c[25]||=i(` It’s your birthday!`,-1),c[26]||=a(`blockquote`,null,[a(`p`,null,`今天是你的生日！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/007.mp3`}),c[27]||=i(),c[28]||=a(`strong`,null,`Tag:`,-1),c[29]||=i(` (entering from her room) Hey.`,-1),c[30]||=a(`blockquote`,null,[a(`p`,null,`（从她的房间进来）嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/008.mp3`}),c[31]||=i(),c[32]||=a(`strong`,null,`Chandler Bing:`,-1),c[33]||=i(` (To Monica) She’s not as pretty as she was when she was 29.`,-1),c[34]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）她不像29岁时那么漂亮了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/009.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`Tag:`,-1),c[37]||=i(` Ms. Green would like to establish some ground rules before she comes out. She would appreciate it if you don’t use the words old or downhill or (To Joey) they still look pretty damn good. (Joey smiles and everyone glares at him.)`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`格林女士想在她出来之前制定一些基本规则。如果你不用old或downhill（对Joey来说）这些词，她会很感激你的。（乔伊笑了，每个人都瞪着他。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/010.mp3`}),c[39]||=i(),c[40]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[41]||=i(` They do!`,-1),c[42]||=a(`blockquote`,null,[a(`p`,null,`是的！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/011.mp3`}),c[43]||=i(),c[44]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[45]||=i(` Rachel! Come on out! Monica made breakfast!`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`瑞秋！出来吧！莫妮卡做了早餐！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/012.mp3`}),c[47]||=i(),c[48]||=a(`strong`,null,`Monica Geller:`,-1),c[49]||=i(` Chocolate-chip pancakes!`,-1),c[50]||=a(`blockquote`,null,[a(`p`,null,`巧克力薄片煎饼！`)],-1),c[51]||=a(`p`,null,[a(`em`,null,`(There is no response from Rachel.)`)],-1),c[52]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋没有回应。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/013.mp3`}),c[53]||=i(),c[54]||=a(`strong`,null,`Ross Geller:`,-1),c[55]||=i(` We’ve got presents!`,-1),c[56]||=a(`blockquote`,null,[a(`p`,null,`我们有礼物！`)],-1),c[57]||=a(`p`,null,[a(`em`,null,`(She opens the door.)`)],-1),c[58]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她打开门。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/014.mp3`}),c[59]||=i(),c[60]||=a(`strong`,null,`Rachel Green:`,-1),c[61]||=i(` Good ones?`,-1),c[62]||=a(`blockquote`,null,[a(`p`,null,`好的？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/015.mp3`}),c[63]||=i(),c[64]||=a(`strong`,null,`Monica Geller:`,-1),c[65]||=i(` They all came from the list you handed out to us two weeks ago.`,-1),c[66]||=a(`blockquote`,null,[a(`p`,null,`它们都是两周前你发给我们的名单上的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/016.mp3`}),c[67]||=i(),c[68]||=a(`strong`,null,`Rachel Green:`,-1),c[69]||=i(` Well, can I keep the presents and still be 29?`,-1),c[70]||=a(`blockquote`,null,[a(`p`,null,`好吧，我能保留这些礼物，并且仍然是29岁吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/017.mp3`}),c[71]||=i(),c[72]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[73]||=i(` Come on Rach! Look, turning thirty is not that big a deal.`,-1),c[74]||=a(`blockquote`,null,[a(`p`,null,`来吧，瑞秋！看，三十岁没什么大不了的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/018.mp3`}),c[75]||=i(),c[76]||=a(`strong`,null,`Ross Geller:`,-1),c[77]||=i(` Oh really. Is that how you felt when you turned thirty?`,-1),c[78]||=a(`blockquote`,null,[a(`p`,null,`哦，真的。这就是你三十岁时的感受吗？`)],-1),c[79]||=a(`p`,null,`[Flashback to Joey’s thirtieth birthday party. It is being held in Monica and Chandler’s apartment.]`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`[倒叙乔伊的30岁生日派对。派对在莫妮卡和钱德勒的公寓举行。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/019.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[83]||=i(` (screaming) Why God?!! Why?!! We had a deal!! Let the others grow old! Not me!! (He buries his head in Phoebe’s lap for comfort.)`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`（尖叫）为什么上帝？！！为什么？我们说好了！！让其他人变老吧！不是我！！（他把头埋在菲比的大腿上以示安慰。）`)],-1),c[85]||=a(`p`,null,`[Cut back to Rachel’s party, everyone is now eating breakfast, except Rachel.]`,-1),c[86]||=a(`blockquote`,null,[a(`p`,null,`[回到瑞秋的派对，除了瑞秋，所有人都在吃早餐。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/020.mp3`}),c[87]||=i(),c[88]||=a(`strong`,null,`Rachel Green:`,-1),c[89]||=i(` Y’know, I’m still 29 in Guam.`,-1),c[90]||=a(`blockquote`,null,[a(`p`,null,`你知道，我在关岛还是29岁。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/021.mp3`}),c[91]||=i(),c[92]||=a(`strong`,null,`Ross Geller:`,-1),c[93]||=i(` Hey, 30 is not that old! Do you know how old the Earth is?`,-1),c[94]||=a(`blockquote`,null,[a(`p`,null,`嘿，30岁没那么老！你知道地球有多老吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/022.mp3`}),c[95]||=i(),c[96]||=a(`strong`,null,`Rachel Green:`,-1),c[97]||=i(` Late thirties? Oh come on you guys! Is it just me? Am I overreacting to this?`,-1),c[98]||=a(`blockquote`,null,[a(`p`,null,`三十多岁？哦，来吧，伙计们！只是我吗？我是不是反应过度了？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/023.mp3`}),c[99]||=i(),c[100]||=a(`strong`,null,`Chandler Bing:`,-1),c[101]||=i(` No Rach, it’s not just you. My thirtieth birthday certainly wasn’t that much fun.`,-1),c[102]||=a(`blockquote`,null,[a(`p`,null,`不，瑞秋，不只是你。我三十岁的生日当然没那么有趣。`)],-1),c[103]||=a(`p`,null,`[Flashback to Chandler’s thirtieth birthday party. It is also being held in Monica and his apartment. He is about to blow out the candles on his birthday cake.]`,-1),c[104]||=a(`blockquote`,null,[a(`p`,null,`[回忆钱德勒的30岁生日派对。派对也在莫妮卡和他的公寓举行。他正要吹灭生日蛋糕上的蜡烛。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/024.mp3`}),c[105]||=t(` <strong>Joey Tribbiani:</strong> (screaming) And now Chandler! We’re all gettin’ so old! (Looking up) Why are you doing this to us?! (Turns away crying.)<blockquote><p>（尖叫）现在是钱德勒！我们都老了！（抬头）你为什么这样对我们？！（哭着转过身去。）</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Joey and Rachel&#39;s, breakfast is finished but Rachel’s still down.</em></p><blockquote><p>🎬 <em>乔伊和瑞秋家，早餐吃完了，但瑞秋还没起床。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E14/025.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Monica Geller:`,-1),c[108]||=i(` Rach, you’re in a great place in your life. Come on, you’ve got a great job! Good friends…`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`瑞秋，你在你的生活中处于一个很好的位置。来吧，你有一份很棒的工作！好朋友…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/026.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[112]||=i(` Yeah, you’re roommate is a soap opera star.`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`是啊，你的室友是个肥皂剧明星。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/027.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Rachel Green:`,-1),c[116]||=i(` Look, y’know I know my life’s going pretty well, but I look around and I just see so many people who’ve accomplished so many other goals by the time they’re thirty.`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`听着，你知道我的生活很顺利，但是我环顾四周，我看到很多人在三十岁的时候完成了很多其他的目标。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/028.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[120]||=i(` Yeah, but you shouldn’t compare yourself to me.`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`是啊，但你不应该拿自己和我比较。`)],-1),c[122]||=a(`p`,null,`[Flashback to: The Street in front of Central Perk, Ross and Joey are holding a yellow tape across the road and everyone is cheering Phoebe as she bounces around the corner on a hippity-hop.]`,-1),c[123]||=a(`blockquote`,null,[a(`p`,null,`[倒叙：中央公园前的街道上，罗斯和乔伊拿着黄色胶带穿过马路，当菲比在街角蹦蹦跳跳时，每个人都在为她欢呼。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/029.mp3`}),c[124]||=i(),c[125]||=a(`strong`,null,`All:`,-1),c[126]||=i(` Come on Phoebe! You can do it Phoebe! Come on!`,-1),c[127]||=a(`blockquote`,null,[a(`p`,null,`来吧，菲比！菲比，你能行！来吧`)],-1),r(p,{src:`/audio/friends/S07/S07E14/030.mp3`}),c[128]||=i(),c[129]||=a(`strong`,null,`Rachel Green:`,-1),c[130]||=i(` There you go!`,-1),c[131]||=a(`blockquote`,null,[a(`p`,null,`好了！`)],-1),c[132]||=a(`p`,null,[a(`em`,null,`(She crosses the line and they all cheer again.)`)],-1),c[133]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她越线了，他们又都欢呼起来。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/031.mp3`}),c[134]||=i(),c[135]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[136]||=i(` I did it! One mile on a hippity-hop! That’s it!! That’s everything I wanted to do before I was thirty. Oh, except I wanted to patch things up with my sister. But oh well. Yay!! (They all cheer again.) And-and girls this thing is a Godsend if you know what I mean. (Rachel and Monica look intrigued and as they all head into Central Perk, Rachel picks up the hippity-hop that Phoebe left behind.)`,-1),c[137]||=a(`blockquote`,null,[a(`p`,null,`我做到了！嬉皮舞步一英里！就这样！！这就是我三十岁以前想做的一切。哦，除了我想和我妹妹和好。但是哦，好吧。耶！！（他们再次欢呼）女孩们，如果你们明白我的意思，这件事是天赐的。（瑞秋和莫妮卡看起来很好奇，当他们都走进中央咖啡馆时，瑞秋拿起了菲比留下的嬉皮舞步。）`)],-1),c[138]||=a(`hr`,null,null,-1),c[139]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, continued from earlier.`)],-1),c[140]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋的，从早些时候开始继续`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/032.mp3`}),c[141]||=i(),c[142]||=a(`strong`,null,`Rachel Green:`,-1),c[143]||=i(` Thirty. Ugh, I mean thirty! Monica, do you remember mean, old Mrs. Kreeger in the fifth grade? She was thirty!`,-1),c[144]||=a(`blockquote`,null,[a(`p`,null,`三十。啊，我是说三十！莫妮卡，你还记得五年级的克雷格老太太吗？她三十岁！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/033.mp3`}),c[145]||=i(),c[146]||=a(`strong`,null,`Tag:`,-1),c[147]||=i(` Come on, let’s have some fun. Huh? (To Rachel) What do you want to do today?`,-1),c[148]||=a(`blockquote`,null,[a(`p`,null,`来吧，让我们玩得开心点。嗯？（对瑞秋）你今天想做什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/034.mp3`}),c[149]||=i(),c[150]||=a(`strong`,null,`Rachel Green:`,-1),c[151]||=i(` Nothing. I don’t want to do anything.`,-1),c[152]||=a(`blockquote`,null,[a(`p`,null,`没什么。我什么都不想做。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/035.mp3`}),c[153]||=i(),c[154]||=a(`strong`,null,`Monica Geller:`,-1),c[155]||=i(` Well, doing nothing on your thirtieth is better than doing something stupid, like Ross.`,-1),c[156]||=a(`blockquote`,null,[a(`p`,null,`嗯，三十多岁的时候什么都不做总比做罗斯那样的蠢事好。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/036.mp3`}),c[157]||=i(),c[158]||=a(`strong`,null,`Ross Geller:`,-1),c[159]||=i(` Hey! That was a practical purchase! I needed that car for transportation! Okay? I-I have a child!`,-1),c[160]||=a(`blockquote`,null,[a(`p`,null,`嘿！这是一个实际的购买！我需要那辆车来运输！可以我有个孩子！`)],-1),c[161]||=a(`p`,null,`[Flashback to: A street, Ross is sitting in his newly purchased MGB. Which is one of the better British sports cars ever made. Of course, ‘better’ is a relative term. Which reminds me of a joke. Why don’t the British make computers? Because they couldn’t figure out how to make them leak oil. Anyway, the gang is all staring at his new purchase.]`,-1),c[162]||=a(`blockquote`,null,[a(`p`,null,`[回忆：一条街上，罗斯坐在他新买的MGB里。这是英国有史以来最好的跑车之一。当然，“更好”是一个相对的词。这让我想起了一个笑话。为什么英国人不生产电脑？因为他们不知道如何让电脑漏油。不管怎样，这帮人都在盯着他的新购买。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/037.mp3`}),c[163]||=i(),c[164]||=a(`strong`,null,`Ross Geller:`,-1),c[165]||=i(` How hot do I look in this, huh?!`,-1),c[166]||=a(`blockquote`,null,[a(`p`,null,`我穿这件衣服看起来有多性感啊？！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/038.mp3`}),c[167]||=i(),c[168]||=a(`strong`,null,`Chandler Bing:`,-1),c[169]||=i(` Ross, a sports car? Wouldn’t it have been cheaper to just stuff a sock down there?`,-1),c[170]||=a(`blockquote`,null,[a(`p`,null,`罗斯，一辆跑车？在那里塞一只袜子不是更便宜吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/039.mp3`}),c[171]||=i(),c[172]||=a(`strong`,null,`Ross Geller:`,-1),c[173]||=i(` That’s not what this is about okay? I-I am a sports car enthusiast. I have always been into cars.`,-1),c[174]||=a(`blockquote`,null,[a(`p`,null,`事情不是这样的好吗？我是一个跑车爱好者。我一直喜欢汽车。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/040.mp3`}),c[175]||=i(),c[176]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[177]||=i(` Hey, what’s the horsepower on this thing?`,-1),c[178]||=a(`blockquote`,null,[a(`p`,null,`嘿，这东西的马力是多少？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/041.mp3`}),c[179]||=i(),c[180]||=a(`strong`,null,`Ross Geller:`,-1),c[181]||=i(` (giddy) I don’t know, but-but look how shiny!`,-1),c[182]||=a(`blockquote`,null,[a(`p`,null,`（头晕）我不知道，但看看有多亮！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/042.mp3`}),c[183]||=i(),c[184]||=a(`strong`,null,`Monica Geller:`,-1),c[185]||=i(` I can’t believe you bought this.`,-1),c[186]||=a(`blockquote`,null,[a(`p`,null,`真不敢相信你买了这个。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/043.mp3`}),c[187]||=i(),c[188]||=a(`strong`,null,`Rachel Green:`,-1),c[189]||=i(` Really! God Ross, what were you thinking? (To Phoebe, quietly) I know it’s really shallow, but a part of me wants him again.`,-1),c[190]||=a(`blockquote`,null,[a(`p`,null,`真的！天哪，罗斯，你在想什么？（悄悄地对菲比说）我知道这很肤浅，但我的一部分又想要他。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/044.mp3`}),c[191]||=i(),c[192]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[193]||=i(` Oh, well get in line missy. (To Ross) So, can I have a ride stud?`,-1),c[194]||=a(`blockquote`,null,[a(`p`,null,`哦，好吧，小姐。（对罗斯）那么，我能要一个骑行钉吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/045.mp3`}),c[195]||=i(),c[196]||=a(`strong`,null,`Ross Geller:`,-1),c[197]||=i(` Hop in. (Phoebe hops in.) Get ready for the smoothest ride of your life.`,-1),c[198]||=a(`blockquote`,null,[a(`p`,null,`上车。（菲比跳了进来。）准备好迎接人生中最顺利的旅程。`)],-1),c[199]||=a(`p`,null,[a(`em`,null,`(He starts the car and surprisingly in fires right up and comes to a nice idle. (Both can be rarities with British sports cars with their lovely Lucas ignition systems, which tend not to work especially in the rain.) Anyway, this being New York he is parallel parked on a street with the car in front of him only inches ahead of his bumper, likewise with the car behind him. He’s completely boxed in and can’t move more than two inches. He tries to get out several times by bumping the bumpers of both cars to no avail.)`)],-1),c[200]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他启动了汽车，令人惊讶的是，他马上就着火了，然后很好地停了下来。（这两款车都是英国跑车的稀罕之物，因为英国跑车配备了可爱的卢卡斯点火系统，特别是在雨中，点火系统往往不起作用。）不管怎么说，在纽约，他平行停放在街道上，前面的车离保险杠只有几英寸远，后面的车也一样。他完全被困在车内，不能移动超过两英寸。他试图通过撞两辆车的保险杠几次逃出，但都没有用。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/046.mp3`}),c[201]||=i(),c[202]||=a(`strong`,null,`Ross Geller:`,-1),c[203]||=i(` Damnit! (Shuts the car off.)`,-1),c[204]||=a(`blockquote`,null,[a(`p`,null,`该死！（关闭汽车。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/047.mp3`}),c[205]||=i(),c[206]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[207]||=i(` (getting out) Okay, who’s next?`,-1),c[208]||=a(`blockquote`,null,[a(`p`,null,`（出来）好的，下一个是谁？`)],-1),c[209]||=a(`hr`,null,null,-1),c[210]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, Phoebe is pouring Rachel some coffee.`)],-1),c[211]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋家，菲比正在给瑞秋倒咖啡。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/048.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Rachel Green:`,-1),c[214]||=i(` Y’know what? I am going to do something today. I’m not just gonna sit around like some old lady. I’m gonna get something pierced. Like my uh, like my nose or my tongue or something.`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`你知道吗？我今天要做点什么。我不会像个老太太那样坐着。我要穿点东西。比如我的鼻子舌头什么的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/049.mp3`}),c[216]||=i(),c[217]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[218]||=i(` Really?! ‘Cause y’know that hurts.`,-1),c[219]||=a(`blockquote`,null,[a(`p`,null,`真的吗因为你知道那很痛。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/050.mp3`}),c[220]||=i(),c[221]||=a(`strong`,null,`Rachel Green:`,-1),c[222]||=i(` So what?! Y’know what? The way I see it—(Phoebe pulls out a hair from the back of her head)—Ow! Son of a bitch!!`,-1),c[223]||=a(`blockquote`,null,[a(`p`,null,`那又怎样？！你知道吗？在我看来-（菲比从她的后脑勺拔出一根头发）-噢！狗娘养的！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/051.mp3`}),c[224]||=i(),c[225]||=a(`strong`,null,`Tag:`,-1),c[226]||=i(` Look Rachel, I know what you’re going through. I’m totally freaked about turning 25.`,-1),c[227]||=a(`blockquote`,null,[a(`p`,null,`听着，瑞秋，我知道你在经历什么。我快25岁了，真是吓坏了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/052.mp3`}),c[228]||=i(),c[229]||=a(`strong`,null,`Rachel Green:`,-1),c[230]||=i(` (glares at him) Get out, get out of my apartment.`,-1),c[231]||=a(`blockquote`,null,[a(`p`,null,`（怒视着他）滚出，滚出我的公寓。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/053.mp3`}),c[232]||=i(),c[233]||=a(`strong`,null,`Monica Geller:`,-1),c[234]||=i(` All right Rach, for what it’s worth, I think that you’re doing great. I mean y’know let’s face it, no one handles this well.`,-1),c[235]||=a(`blockquote`,null,[a(`p`,null,`好吧，瑞秋，无论如何，我认为你做得很好。我是说，你知道，让我们面对现实吧，没人能处理好这件事。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/054.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[238]||=i(` Least of all you.`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`至少是你。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/055.mp3`}),c[240]||=i(),c[241]||=a(`strong`,null,`Tag:`,-1),c[242]||=i(` Why? What you’d do?`,-1),c[243]||=a(`blockquote`,null,[a(`p`,null,`为什么？你会怎么做？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/056.mp3`}),c[244]||=i(),c[245]||=a(`strong`,null,`Monica Geller:`,-1),c[246]||=i(` Weren’t you asked to leave sonny?`,-1),c[247]||=a(`blockquote`,null,[a(`p`,null,`你不是被要求离开桑尼吗？`)],-1),c[248]||=a(`p`,null,`[Flashback to Monica and Chandler’s apartment. Chandler has a bunch of people over in formal wear to give Monica a surprise birthday party. Joey is coming out of the bathroom and removing his tie.]`,-1),c[249]||=a(`blockquote`,null,[a(`p`,null,`[倒叙莫妮卡和钱德勒的公寓。钱德勒有一群穿着正装的人过来给莫妮卡一个惊喜的生日派对。乔伊从浴室出来，脱下领带。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/057.mp3`}),c[250]||=i(),c[251]||=a(`strong`,null,`Chandler Bing:`,-1),c[252]||=i(` (To Joey) Would you put that back on?! Monica’s gonna be here any minute!`,-1),c[253]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）你能把它穿回去吗？！莫妮卡随时都会来！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/058.mp3`}),c[254]||=i(),c[255]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[256]||=i(` But it hurt’s my Joey’s Apple.`,-1),c[257]||=a(`blockquote`,null,[a(`p`,null,`但那是我乔伊的苹果。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/059.mp3`}),c[258]||=i(),c[259]||=a(`strong`,null,`Chandler Bing:`,-1),c[260]||=i(` (frustrated) Okay, for the last time. It’s not named for each individual man.`,-1),c[261]||=a(`blockquote`,null,[a(`p`,null,`（沮丧地）好吧，最后一次。它不是为每个人命名的。`)],-1),c[262]||=a(`p`,null,[a(`em`,null,`(Joey walks away and Mr. and Mrs. Geller walk up. Mr. Geller is wearing this ancient velvet tuxedo.)`)],-1),c[263]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊走开了，盖勒夫妇走了过来。盖勒先生穿着这件古老的天鹅绒晚礼服。）`)])],-1),c[264]||=a(`p`,null,`Mrs. Geller: (To Chandler) You’ve done a wonderful job with this party Chandler. Everything looks so lovely.`,-1),c[265]||=a(`blockquote`,null,[a(`p`,null,`（对钱德勒）你在这个聚会上做得很好，钱德勒。一切看起来都很可爱。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/060.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Chandler Bing:`,-1),c[268]||=i(` Oh well, not as lovely as you. I mean, I can’t believe that you would have a thirty-year-old daughter! (To Mr. Geller) And you! I can’t believe that you would have a tux that’s thirty years old! (Puts his hand on Mr. Geller’s shoulder.)`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`哦，没有你那么可爱。我是说，我真不敢相信你会有一个三十岁的女儿！（对盖勒先生）还有你！我真不敢相信你会穿三十岁的晚礼服！（把手放在盖勒先生的肩膀上。）`)],-1),c[270]||=a(`p`,null,`Mr. Geller: It’s older than that. Ross was actually conceived right near this tuxedo.`,-1),c[271]||=a(`blockquote`,null,[a(`p`,null,`它比那还要古老。罗斯实际上就是在这件燕尾服附近怀上的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/061.mp3`}),c[272]||=i(),c[273]||=a(`strong`,null,`Chandler Bing:`,-1),c[274]||=i(` Ohh! (He quickly removes his hand and looks at it.)`,-1),c[275]||=a(`blockquote`,null,[a(`p`,null,`哦！（他迅速把手移开，看了看。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/062.mp3`}),c[276]||=i(),c[277]||=a(`strong`,null,`Rachel Green:`,-1),c[278]||=i(` (entering) Hey! Everybody hide! Hide! I saw her! She’s coming!`,-1),c[279]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！大家都躲起来！隐藏我看见她了！她来了！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/063.mp3`}),c[280]||=i(),c[281]||=a(`strong`,null,`Chandler Bing:`,-1),c[282]||=i(` Okay! Okay! Everybody down! Everybody down! (Rachel turns off the lights and everyone crouches. As everyone crouches, a ripping noise erupts from the assemblage.)`,-1),c[283]||=a(`blockquote`,null,[a(`p`,null,`好的！可以大家都趴下！大家都趴下！（瑞秋关了灯，大家都蹲下。当大家蹲下时，一种撕裂的声音从集合中爆发。）`)],-1),c[284]||=a(`p`,null,`Mr. Geller: Crap.`,-1),c[285]||=a(`blockquote`,null,[a(`p`,null,`废话。`)],-1),c[286]||=a(`p`,null,[a(`em`,null,`(We hear some fumbling at the door, then silence.)`)],-1),c[287]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（我们听到有人在门口摸索，然后是沉默。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/064.mp3`}),c[288]||=i(),c[289]||=a(`strong`,null,`Chandler Bing:`,-1),c[290]||=i(` (getting up to investigate) Okay, everybody stay here. I will find out what’s going on.`,-1),c[291]||=a(`blockquote`,null,[a(`p`,null,`（站起来调查）好的，大家呆在这里。我会查清楚到底发生了什么。`)],-1),c[292]||=a(`p`,null,[a(`em`,null,`(He goes out into the hall and finds a very drunk Monica lying up against Joey and Rachel’s door.)`)],-1),c[293]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他走出大厅，发现一个喝醉了的莫妮卡靠在乔伊和瑞秋的门上。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/065.mp3`}),c[294]||=i(),c[295]||=a(`strong`,null,`Monica Geller:`,-1),c[296]||=i(` Heyyy!! You got the door open!! (Giggles.)`,-1),c[297]||=a(`blockquote`,null,[a(`p`,null,`嘿！！你把门打开了！！（咯咯地笑。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/066.mp3`}),c[298]||=i(),c[299]||=a(`strong`,null,`Chandler Bing:`,-1),c[300]||=i(` Hey-hey are you drunk?`,-1),c[301]||=a(`blockquote`,null,[a(`p`,null,`嘿，嘿，你喝醉了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/067.mp3`}),c[302]||=i(),c[303]||=a(`strong`,null,`Monica Geller:`,-1),c[304]||=i(` Nooo! (Giggles) Okay. (She tries to pull herself up by Rachel and Joey’s doorknob, but the door opens and she almost falls into the their apartment. She manages to catch herself.) Whoa! (Stands up, unsteadily) Okay. See I was, I was a little nervous about turning (whispering) thirty. (Giggles.) So the bus boys took me out for some drinks. (Pause) I wanna puke on you later!`,-1),c[305]||=a(`blockquote`,null,[a(`p`,null,`不！（咯咯笑）好的。（她试图靠着瑞秋和乔伊的门把手把自己拉起来，但门开了，她差点掉进他们的公寓。她设法抓住了自己。）哇！（站起来，摇摇晃晃）好的。看到了吧，我有点紧张，快三十岁了。（咯咯笑）于是巴士司机带我出去喝了几杯。（停顿）我想晚一点吐在你身上！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/068.mp3`}),c[306]||=i(),c[307]||=a(`strong`,null,`Chandler Bing:`,-1),c[308]||=i(` Okay, here is the thing. We have thrown a very formal surprise party for you in there! All of your friends are in there and your parents!`,-1),c[309]||=a(`blockquote`,null,[a(`p`,null,`好吧，事情是这样的。我们在那里为你举办了一个非常正式的惊喜派对！你所有的朋友和你的父母都在里面！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/069.mp3`}),c[310]||=i(),c[311]||=a(`strong`,null,`Monica Geller:`,-1),c[312]||=i(` Noo!!!`,-1),c[313]||=a(`blockquote`,null,[a(`p`,null,`不！！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/070.mp3`}),c[314]||=i(),c[315]||=a(`strong`,null,`Chandler Bing:`,-1),c[316]||=i(` Yes!`,-1),c[317]||=a(`blockquote`,null,[a(`p`,null,`是的！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/071.mp3`}),c[318]||=i(),c[319]||=a(`strong`,null,`Monica Geller:`,-1),c[320]||=i(` Noo!!`,-1),c[321]||=a(`blockquote`,null,[a(`p`,null,`不！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/072.mp3`}),c[322]||=i(),c[323]||=a(`strong`,null,`Chandler Bing:`,-1),c[324]||=i(` Yes!!`,-1),c[325]||=a(`blockquote`,null,[a(`p`,null,`是的！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/073.mp3`}),c[326]||=i(),c[327]||=a(`strong`,null,`Monica Geller:`,-1),c[328]||=i(` Oh no! My parents have never seen me drunk! (Pause) That they know of.`,-1),c[329]||=a(`blockquote`,null,[a(`p`,null,`哦，不！我父母从没见过我喝醉！（停顿）他们知道的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/074.mp3`}),c[330]||=i(),c[331]||=a(`strong`,null,`Chandler Bing:`,-1),c[332]||=i(` Okay, here’s the thing. We’re gonna get you some coffee and they will never know that you’re drunk.`,-1),c[333]||=a(`blockquote`,null,[a(`p`,null,`好吧，事情是这样的。我们给你弄点咖啡，他们永远不会知道你喝醉了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/075.mp3`}),c[334]||=i(),c[335]||=a(`strong`,null,`Monica Geller:`,-1),c[336]||=i(` Really?! You promise?`,-1),c[337]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！你保证？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/076.mp3`}),c[338]||=i(),c[339]||=a(`strong`,null,`Chandler Bing:`,-1),c[340]||=i(` Yeah, I’ll take care of it.`,-1),c[341]||=a(`blockquote`,null,[a(`p`,null,`是的，我会处理的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/077.mp3`}),c[342]||=i(),c[343]||=a(`strong`,null,`Monica Geller:`,-1),c[344]||=i(` Okay. I love you so much. (Kisses him.)`,-1),c[345]||=a(`blockquote`,null,[a(`p`,null,`好的。我非常爱你。（吻他。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/078.mp3`}),c[346]||=i(),c[347]||=a(`strong`,null,`Chandler Bing:`,-1),c[348]||=i(` (laughing) Okay we have to do something about your breath.`,-1),c[349]||=a(`blockquote`,null,[a(`p`,null,`（笑）好吧，我们得对你的呼吸做点什么。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/079.mp3`}),c[350]||=i(),c[351]||=a(`strong`,null,`Monica Geller:`,-1),c[352]||=i(` What about your breath?! (Breathes on him.)`,-1),c[353]||=a(`blockquote`,null,[a(`p`,null,`你的呼吸呢？！（对着他呼吸。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/080.mp3`}),c[354]||=i(),c[355]||=a(`strong`,null,`Chandler Bing:`,-1),c[356]||=i(` That’s still yours. Okay, now remember it’s a surprise party. So, when you go in, act surprised.`,-1),c[357]||=a(`blockquote`,null,[a(`p`,null,`那还是你的。好的，现在记住这是一个惊喜派对。所以，当你进去的时候，表现得很惊讶。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/081.mp3`}),c[358]||=i(),c[359]||=a(`strong`,null,`Monica Geller:`,-1),c[360]||=i(` Okay. I can do that.`,-1),c[361]||=a(`blockquote`,null,[a(`p`,null,`好的。我能做到。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/082.mp3`}),c[362]||=i(),c[363]||=a(`strong`,null,`Chandler Bing:`,-1),c[364]||=i(` Okay.`,-1),c[365]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),c[366]||=a(`p`,null,[a(`em`,null,`(Chandler opens the door and Monica sneaks up on it. They go inside.)`)],-1),c[367]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒打开门，莫妮卡偷偷走了上去。他们走了进去。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/083.mp3`}),c[368]||=t(` <strong>All:</strong> Surprise!!!<blockquote><p>惊喜！！！</p></blockquote><p><em>(Monica screams and they all stare at her.)</em></p><blockquote><p><em>（莫妮卡尖叫着，他们都盯着她看。）</em></p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Ross’s birthday, Joey is now trying to get his car out while Ross is directing him.</em></p><blockquote><p>🎬 <em>罗斯的生日，乔伊正试图把车开出来，而罗斯正在指挥他。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S07/S07E14/084.mp3`}),c[369]||=i(),c[370]||=a(`strong`,null,`Ross Geller:`,-1),c[371]||=i(` Okay, forward. Forward—Stop! (The car moves an inch and Ross runs to the back of the car.) Okay, back—Stop! (The car barely moves and Ross runs back to the front.) Okay, forward—Stop! Stop! Stop!`,-1),c[372]||=a(`blockquote`,null,[a(`p`,null,`好的，向前。前进停止！（汽车移动了一英寸，罗斯跑到汽车后部。）好的，后退！（汽车几乎一动不动，罗斯跑回车头。）好的，向前停下！停止停止`)],-1),r(p,{src:`/audio/friends/S07/S07E14/085.mp3`}),c[373]||=i(),c[374]||=a(`strong`,null,`Monica Geller:`,-1),c[375]||=i(` Ross, just forget about it. This guy’s got you totally wedged in.`,-1),c[376]||=a(`blockquote`,null,[a(`p`,null,`罗斯，算了吧。这家伙让你完全陷入困境。`)],-1),c[377]||=a(`p`,null,[a(`em`,null,`(A beautiful woman approaches.)`)],-1),c[378]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（一位美女走近。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/086.mp3`}),c[379]||=i(),c[380]||=a(`strong`,null,`Woman:`,-1),c[381]||=i(` (To Joey) Is this yours?`,-1),c[382]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）这是你的吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/087.mp3`}),c[383]||=i(),c[384]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[385]||=i(` Well actually…`,-1),c[386]||=a(`blockquote`,null,[a(`p`,null,`事实上…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/088.mp3`}),c[387]||=i(),c[388]||=a(`strong`,null,`Ross Geller:`,-1),c[389]||=i(` No-no-no! It’s mine! It’s-it’s mine. (The woman walks away.)`,-1),c[390]||=a(`blockquote`,null,[a(`p`,null,`不，不！是我的！是我的。（女人走开了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/089.mp3`}),c[391]||=i(),c[392]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[393]||=i(` Dude, you soooo need this car.`,-1),c[394]||=a(`blockquote`,null,[a(`p`,null,`老兄，你太需要这辆车了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/090.mp3`}),c[395]||=t(` <strong>Phoebe Buffay:</strong> (running up) Okay. Okay, here’s what we’re gonna do. Okay, I’m gonna break into this mini-van and put it in neutral. You guys push it forward so Ross can drive out of his spot. Okay? All right, here we go. (She opens her coat and reveals that thing car thieves use to break into cars as Ross jumps in behind the wheel. She inserts the device, unlocks the door, opens it, and the alarm goes off.) Haul ass!!!! (Runs off.)<blockquote><p>（跑上来）好的。好的，这是我们要做的。好吧，我要冲进这辆小货车，把它放在空档。你们把它往前推，这样罗斯就可以开车离开他的位置了。可以好了，开始吧。（她打开外套，发现罗斯跳到方向盘后面时偷车贼用来闯入汽车的东西。她插入装置，开锁，打开门，闹钟响了。）拉屁股！！！！（跑掉了。）</p></blockquote><p><em>(The rest of the gang runs away, except for Ross who’s tramped inside his car. To hide he puts the top up as Monica, Rachel, and Joey come running past.)</em></p><blockquote><p><em>（除了被踩在车里的罗斯，其他人都跑开了。莫妮卡、瑞秋和乔伊跑过时，为了躲藏，他把车顶盖了起来。）</em></p></blockquote><hr><p>🎬 <em>Phoebe’s birthday, she’s taking the hippity-hop to Ursula’s apartment as a gift. She knocks on the door and Ursula answers it.</em></p><blockquote><p>🎬 <em>菲比的生日，她带着嬉皮舞步去乌苏拉的公寓作为礼物。她敲门，乌苏拉应门。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E14/091.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[398]||=i(` Happy thirtieth birthday! Here! (Hands her the hippity-hop.) It’s for the child in you, and the woman. Happy thirtieth!`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`三十岁生日快乐！在这里（递给她嬉皮舞步。）这是为了你的孩子和女人。三十岁快乐！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/092.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`Ursula:`,-1),c[402]||=i(` Right, why do you keep saying that?`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`对，你为什么一直这么说？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/093.mp3`}),c[404]||=i(),c[405]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[406]||=i(` Because it’s our thirtieth birthday.`,-1),c[407]||=a(`blockquote`,null,[a(`p`,null,`因为今天是我们的三十岁生日。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/094.mp3`}),c[408]||=i(),c[409]||=a(`strong`,null,`Ursula:`,-1),c[410]||=i(` Yeah, no we’re not thirty. We’re 31. Okay. (She closes the door.)`,-1),c[411]||=a(`blockquote`,null,[a(`p`,null,`是的，不，我们不是三十岁。我们31岁了。可以（她关上门。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/095.mp3`}),c[412]||=i(),c[413]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[414]||=i(` Wait! (Knocks on the door and Ursula opens it.)`,-1),c[415]||=a(`blockquote`,null,[a(`p`,null,`等等！（敲了敲门，厄秀拉打开了门。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/096.mp3`}),c[416]||=i(),c[417]||=a(`strong`,null,`Ursula:`,-1),c[418]||=i(` Oh, it’s you.`,-1),c[419]||=a(`blockquote`,null,[a(`p`,null,`哦，是你。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/097.mp3`}),c[420]||=i(),c[421]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[422]||=i(` Yeah. What?!`,-1),c[423]||=a(`blockquote`,null,[a(`p`,null,`是的。什么？！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/098.mp3`}),c[424]||=i(),c[425]||=a(`strong`,null,`Ursula:`,-1),c[426]||=i(` Yeah, we’re not thirty, we’re 31.`,-1),c[427]||=a(`blockquote`,null,[a(`p`,null,`是的，我们不是30岁，我们是31岁。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/099.mp3`}),c[428]||=i(),c[429]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[430]||=i(` Nu-uh!`,-1),c[431]||=a(`blockquote`,null,[a(`p`,null,`努恩！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/100.mp3`}),c[432]||=i(),c[433]||=a(`strong`,null,`Ursula:`,-1),c[434]||=i(` Yea-huh! That’s what is says on my birth certificate.`,-1),c[435]||=a(`blockquote`,null,[a(`p`,null,`是啊！这是我出生证明上写的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/101.mp3`}),c[436]||=i(),c[437]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[438]||=i(` You have your birth certificate?`,-1),c[439]||=a(`blockquote`,null,[a(`p`,null,`你有出生证明吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/102.mp3`}),c[440]||=i(),c[441]||=a(`strong`,null,`Ursula:`,-1),c[442]||=i(` Yeah, I got a big box of family stuff when my mom died.`,-1),c[443]||=a(`blockquote`,null,[a(`p`,null,`是的，我妈妈去世时，我得到了一大盒家庭用品。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/103.mp3`}),c[444]||=i(),c[445]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[446]||=i(` Our mom.`,-1),c[447]||=a(`blockquote`,null,[a(`p`,null,`我们的妈妈。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/104.mp3`}),c[448]||=i(),c[449]||=a(`strong`,null,`Ursula:`,-1),c[450]||=i(` (sarcastic) Right! Okay. (Hands Phoebe her births certificate.)`,-1),c[451]||=a(`blockquote`,null,[a(`p`,null,`（讽刺地）对！可以（递给菲比她的出生证。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/105.mp3`}),c[452]||=i(),c[453]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[454]||=i(` Do you have my birth certificate?`,-1),c[455]||=a(`blockquote`,null,[a(`p`,null,`你有我的出生证明吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/106.mp3`}),c[456]||=i(),c[457]||=a(`strong`,null,`Ursula:`,-1),c[458]||=i(` No, I sold it to a Swedish runaway.`,-1),c[459]||=a(`blockquote`,null,[a(`p`,null,`不，我把它卖给了一个瑞典逃犯。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/107.mp3`}),c[460]||=i(),c[461]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[462]||=i(` (reading the certificate) Oh my God! Oh my God, we are 31.`,-1),c[463]||=a(`blockquote`,null,[a(`p`,null,`（读证书）哦，天哪！天啊，我们31岁了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/108.mp3`}),c[464]||=i(),c[465]||=a(`strong`,null,`Ursula:`,-1),c[466]||=i(` Yeah.`,-1),c[467]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/109.mp3`}),c[468]||=i(),c[469]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[470]||=i(` I just lost a whole year of my life.`,-1),c[471]||=a(`blockquote`,null,[a(`p`,null,`我刚刚失去了整整一年的生命。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/110.mp3`}),c[472]||=i(),c[473]||=a(`strong`,null,`Ursula:`,-1),c[474]||=i(` (sarcastic) Okay.`,-1),c[475]||=a(`blockquote`,null,[a(`p`,null,`（讽刺地）好的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/111.mp3`}),c[476]||=i(),c[477]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[478]||=i(` Your middle name is Pamela?`,-1),c[479]||=a(`blockquote`,null,[a(`p`,null,`你的中间名是帕米拉？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/112.mp3`}),c[480]||=i(),c[481]||=a(`strong`,null,`Ursula:`,-1),c[482]||=i(` Yes.`,-1),c[483]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/113.mp3`}),c[484]||=i(),c[485]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[486]||=i(` Well, I never knew mine. Do you remember what it is?`,-1),c[487]||=a(`blockquote`,null,[a(`p`,null,`嗯，我从来不知道我的。你还记得那是什么吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/114.mp3`}),c[488]||=i(),c[489]||=a(`strong`,null,`Ursula:`,-1),c[490]||=i(` Yes! Phoebe.`,-1),c[491]||=a(`blockquote`,null,[a(`p`,null,`是的！菲比。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/115.mp3`}),c[492]||=i(),c[493]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[494]||=i(` That’s my first name.`,-1),c[495]||=a(`blockquote`,null,[a(`p`,null,`那是我的名字。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/116.mp3`}),c[496]||=i(),c[497]||=a(`strong`,null,`Ursula:`,-1),c[498]||=i(` Right, okay, then no.`,-1),c[499]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，那就不要了。`)],-1),c[500]||=a(`hr`,null,null,-1),c[501]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica’s birthday, it’s just after the surprise.`)],-1),c[502]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡的生日，就在惊喜过后。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/117.mp3`}),c[503]||=i(),c[504]||=a(`strong`,null,`Chandler Bing:`,-1),c[505]||=i(` Okay before we start the celebration, Monica has to go put on her party dress.`,-1),c[506]||=a(`blockquote`,null,[a(`p`,null,`好的，在我们开始庆祝之前，莫妮卡必须穿上她的派对礼服。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/118.mp3`}),c[507]||=i(),c[508]||=a(`strong`,null,`Monica Geller:`,-1),c[509]||=i(` Yay!`,-1),c[510]||=a(`blockquote`,null,[a(`p`,null,`耶！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/119.mp3`}),c[511]||=t(` <strong>Chandler Bing:</strong> See? (Does his laugh.) Here we go. (Starts walking her to their room, and has to pass in front of Mr. Geller who’s sitting at the table and Mrs. Geller who’s standing next to him.)<blockquote><p>看到了吗？（他笑了。）我们走了。（开始送她去他们的房间，必须经过坐在桌子旁的盖勒先生和站在他旁边的盖勒太太面前。）</p></blockquote><p>Mr. Geller: Happy birthday, sweetie! Give us a hug! (Starts to get up.)</p><blockquote><p>生日快乐，亲爱的！给我们一个拥抱！（开始起床。）</p></blockquote><p>Mrs. Geller: (stopping him) Don’t get up Jack! The safety pins are about to blow.</p><blockquote><p>（拦住他）别站起来，杰克！安全别针就要爆炸了。</p></blockquote><p><em>(They continue their trek.)</em></p><blockquote><p><em>（他们继续跋涉。）</em></p></blockquote>`,10),r(p,{src:`/audio/friends/S07/S07E14/120.mp3`}),c[512]||=i(),c[513]||=a(`strong`,null,`Monica Geller:`,-1),c[514]||=i(` (sees someone) Paul!`,-1),c[515]||=a(`blockquote`,null,[a(`p`,null,`（看见某人）保罗！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/121.mp3`}),c[516]||=i(),c[517]||=a(`strong`,null,`Chandler Bing:`,-1),c[518]||=i(` (correcting her) Phil.`,-1),c[519]||=a(`blockquote`,null,[a(`p`,null,`（纠正她）菲尔。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/122.mp3`}),c[520]||=i(),c[521]||=a(`strong`,null,`Monica Geller:`,-1),c[522]||=i(` Phil!`,-1),c[523]||=a(`blockquote`,null,[a(`p`,null,`菲尔！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/123.mp3`}),c[524]||=i(),c[525]||=a(`strong`,null,`Chandler Bing:`,-1),c[526]||=i(` Now, there is a dress laid out on your bed. (Monica stumbles on the steps.) Okay, (catches her) you’re doing great. You’re doing great. You’re doing fine.`,-1),c[527]||=a(`blockquote`,null,[a(`p`,null,`现在，你的床上摆着一条裙子。（莫妮卡绊倒在台阶上。）好的，（抓住她）你做得很好。你做得很好。你做得很好。`)],-1),c[528]||=a(`p`,null,[a(`em`,null,`(Phoebe approaches as they almost get to their room.)`)],-1),c[529]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比走近，他们几乎要到自己的房间了。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/124.mp3`}),c[530]||=i(),c[531]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[532]||=i(` Hey, what’s going on?`,-1),c[533]||=a(`blockquote`,null,[a(`p`,null,`嘿，发生什么事了？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/125.mp3`}),c[534]||=i(),c[535]||=a(`strong`,null,`Chandler Bing:`,-1),c[536]||=i(` Monica’s a little drunk.`,-1),c[537]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡有点醉了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/126.mp3`}),c[538]||=i(),c[539]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[540]||=i(` Yay! I love drunk Monica!`,-1),c[541]||=a(`blockquote`,null,[a(`p`,null,`耶！我喜欢喝醉酒的莫妮卡！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/127.mp3`}),c[542]||=i(),c[543]||=a(`strong`,null,`Monica Geller:`,-1),c[544]||=i(` Awwwww… (Giggles.)`,-1),c[545]||=a(`blockquote`,null,[a(`p`,null,`哎呀…（咯咯笑）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/128.mp3`}),c[546]||=i(),c[547]||=a(`strong`,null,`Chandler Bing:`,-1),c[548]||=i(` (To Monica) Go change! (To Phoebe) She doesn’t want her parents to know she’s drunk.`,-1),c[549]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）去换衣服！（对菲比）她不想让父母知道她喝醉了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/129.mp3`}),c[550]||=i(),c[551]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[552]||=i(` Ohh! All right! All right. Here’s what we’ll do, I’ll get twice as drunk as Monica and then no one’s will even notice her.`,-1),c[553]||=a(`blockquote`,null,[a(`p`,null,`哦！好吧好吧这就是我们要做的，我会喝两倍于莫妮卡的酒，然后没人会注意到她。`)],-1),c[554]||=a(`p`,null,[a(`em`,null,`(Chandler walks over to where the rest of the gang is.)`)],-1),c[555]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒走到其他人所在的地方。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/130.mp3`}),c[556]||=i(),c[557]||=a(`strong`,null,`Rachel Green:`,-1),c[558]||=i(` What’s-what’s going on? Phil’s really pissed!`,-1),c[559]||=a(`blockquote`,null,[a(`p`,null,`怎么了？菲尔真的生气了！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/131.mp3`}),c[560]||=i(),c[561]||=a(`strong`,null,`Chandler Bing:`,-1),c[562]||=i(` Monica’s wasted.`,-1),c[563]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡喝醉了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/132.mp3`}),c[564]||=i(),c[565]||=a(`strong`,null,`Ross Geller:`,-1),c[566]||=i(` Maybe that will liven up this party.`,-1),c[567]||=a(`blockquote`,null,[a(`p`,null,`也许这会使这个聚会活跃起来。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/133.mp3`}),c[568]||=i(),c[569]||=a(`strong`,null,`Chandler Bing:`,-1),c[570]||=i(` (To Rachel) Okay, will you just go help her change please!`,-1),c[571]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）好的，请你去帮她换衣服好吗！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/134.mp3`}),c[572]||=i(),c[573]||=a(`strong`,null,`Rachel Green:`,-1),c[574]||=i(` Okay, but taking care of a drunk, naked woman seems like a job for Joey.`,-1),c[575]||=a(`blockquote`,null,[a(`p`,null,`好吧，但是照顾一个喝醉的裸体女人似乎是乔伊的工作。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/135.mp3`}),c[576]||=i(),c[577]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[578]||=i(` Yep. (Starts for Monica’s room, but Chandler stops him.)`,-1),c[579]||=a(`blockquote`,null,[a(`p`,null,`是的。（出发去莫妮卡的房间，但钱德勒阻止了他。）`)],-1),c[580]||=a(`hr`,null,null,-1),c[581]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Rachel’s birthday, everyone is presenting their presents to Rachel.`)],-1),c[582]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`瑞秋的生日，每个人都在给瑞秋送礼物。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/136.mp3`}),c[583]||=i(),c[584]||=a(`strong`,null,`Tag:`,-1),c[585]||=i(` (handing his to her) This one’s from me.`,-1),c[586]||=a(`blockquote`,null,[a(`p`,null,`（把他的手递给她）这是我的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/137.mp3`}),c[587]||=i(),c[588]||=a(`strong`,null,`Rachel Green:`,-1),c[589]||=i(` Ahh!`,-1),c[590]||=a(`blockquote`,null,[a(`p`,null,`啊！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/138.mp3`}),c[591]||=i(),c[592]||=a(`strong`,null,`Tag:`,-1),c[593]||=i(` It wasn’t on your list, but hopefully you’ll think it’s really fun.`,-1),c[594]||=a(`blockquote`,null,[a(`p`,null,`它不在你的名单上，但希望你会觉得它真的很有趣。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/139.mp3`}),c[595]||=i(),c[596]||=a(`strong`,null,`Rachel Green:`,-1),c[597]||=i(` (opening it) A scooter! (She’s not happy.)`,-1),c[598]||=a(`blockquote`,null,[a(`p`,null,`（打开）一辆滑板车！（她不高兴。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/140.mp3`}),c[599]||=i(),c[600]||=a(`strong`,null,`Ross Geller:`,-1),c[601]||=i(` (to Tag) Stick to the list. Always stick to the list.`,-1),c[602]||=a(`blockquote`,null,[a(`p`,null,`（贴上标签）坚持名单。始终遵守清单。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/141.mp3`}),c[603]||=i(),c[604]||=a(`strong`,null,`Rachel Green:`,-1),c[605]||=i(` No! No-no, I love it. Thank you. (Kisses him.)`,-1),c[606]||=a(`blockquote`,null,[a(`p`,null,`不！不，不，我喜欢。非常感谢。（吻他。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/142.mp3`}),c[607]||=i(),c[608]||=a(`strong`,null,`Chandler Bing:`,-1),c[609]||=i(` Okay, open ours next. Open ours next!`,-1),c[610]||=a(`blockquote`,null,[a(`p`,null,`好的，下一个打开我们的。打开我们的下一个！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/143.mp3`}),c[611]||=i(),c[612]||=a(`strong`,null,`Rachel Green:`,-1),c[613]||=i(` Okay.`,-1),c[614]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/144.mp3`}),c[615]||=i(),c[616]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[617]||=i(` Now that you’re a couple, we don’t get two presents from you guys?`,-1),c[618]||=a(`blockquote`,null,[a(`p`,null,`既然你们是一对，我们就不会收到你们的两份礼物了？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/145.mp3`}),c[619]||=i(),c[620]||=a(`strong`,null,`Chandler Bing:`,-1),c[621]||=i(` For my last birthday you gave me a hug! (To Rachel) Okay, read the card! Read the card!`,-1),c[622]||=a(`blockquote`,null,[a(`p`,null,`在我最后一个生日，你给了我一个拥抱！（对瑞秋）好的，读卡片！读卡片！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/146.mp3`}),c[623]||=i(),c[624]||=a(`strong`,null,`Rachel Green:`,-1),c[625]||=i(` Okay. (Opens the card and reads it.) Happy birthday Grandma! It’s better to be over the hill (starting to cry) then buried under it. (Breaks down as everyone glares at them.) All our love Monica and Chandler. (Crying) That’s funny, yeah!`,-1),c[626]||=a(`blockquote`,null,[a(`p`,null,`好的。（打开卡片看了看）奶奶生日快乐！最好是翻过小山（开始哭泣），然后埋在下面。（当每个人都盯着他们看时，他们都崩溃了。）我们所有的爱莫妮卡和钱德勒。（哭）真有趣，耶！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/147.mp3`}),c[627]||=i(),c[628]||=a(`strong`,null,`Chandler Bing:`,-1),c[629]||=i(` No-no-no-no! That was the joke!`,-1),c[630]||=a(`blockquote`,null,[a(`p`,null,`不，不，不！这就是笑话！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/148.mp3`}),c[631]||=i(),c[632]||=a(`strong`,null,`Rachel Green:`,-1),c[633]||=i(` (crying) No, I know! I get it! It’s funny!`,-1),c[634]||=a(`blockquote`,null,[a(`p`,null,`（哭）不，我知道！我明白了！真有趣！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/149.mp3`}),c[635]||=i(),c[636]||=a(`strong`,null,`Chandler Bing:`,-1),c[637]||=i(` No, because you’re not a grandmother!`,-1),c[638]||=a(`blockquote`,null,[a(`p`,null,`不，因为你不是祖母！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/150.mp3`}),c[639]||=i(),c[640]||=a(`strong`,null,`Rachel Green:`,-1),c[641]||=i(` No I know, because to be a grandmother you have to be married and have children and I don’t have any of those things. That’s why it’s so funny. (Runs into her room crying.)`,-1),c[642]||=a(`blockquote`,null,[a(`p`,null,`不，我知道，因为要当祖母，你必须结婚生子，而我没有这些东西。这就是为什么它如此有趣。（哭着跑进她的房间。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/151.mp3`}),c[643]||=i(),c[644]||=a(`strong`,null,`Monica Geller:`,-1),c[645]||=i(` All you had to do was buy the card!`,-1),c[646]||=a(`blockquote`,null,[a(`p`,null,`你所要做的就是买这张卡！`)],-1),c[647]||=a(`hr`,null,null,-1),c[648]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Rachel’s birthday, a time lapse has occurred. Rachel is coming back into the living room carrying a notepad.`)],-1),c[649]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`瑞秋的生日，一段时间过去了。瑞秋拿着一个记事本回到客厅。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/152.mp3`}),c[650]||=i(),c[651]||=a(`strong`,null,`Ross Geller:`,-1),c[652]||=i(` Hey! Look who’s back! It’s the birthday girl! How’s the birthday girl feeling?`,-1),c[653]||=a(`blockquote`,null,[a(`p`,null,`嘿！看谁回来了！是生日女孩！过生日的女孩感觉怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/153.mp3`}),c[654]||=i(),c[655]||=a(`strong`,null,`Rachel Green:`,-1),c[656]||=i(` Well, I feel fine, but I think you’re bumming out the rest of the kids.`,-1),c[657]||=a(`blockquote`,null,[a(`p`,null,`嗯，我感觉很好，但我觉得你把其他孩子都累坏了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/154.mp3`}),c[658]||=i(),c[659]||=a(`strong`,null,`Ross Geller:`,-1),c[660]||=i(` What? (Glances over and sees the faces of the rest of the group, then goes and sits down.)`,-1),c[661]||=a(`blockquote`,null,[a(`p`,null,`什么？（扫了一眼，看到了其他人的脸，然后走过去坐下。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/155.mp3`}),c[662]||=i(),c[663]||=a(`strong`,null,`Rachel Green:`,-1),c[664]||=i(` Okay! Y’know what? I realized it was stupid to get upset about not having a husband and kids. All I really needed was a plan. See I wanna have three kids…`,-1),c[665]||=a(`blockquote`,null,[a(`p`,null,`好的！你知道吗？我意识到为没有丈夫和孩子而烦恼是愚蠢的。我真正需要的只是一个计划。看，我想要三个孩子…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/156.mp3`}),c[666]||=i(),c[667]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[668]||=i(` Oh let me guess, and you wanna have them all at the same time and you wanna have them for your brother.`,-1),c[669]||=a(`blockquote`,null,[a(`p`,null,`哦，让我猜猜，你想同时拥有它们，你想把它们送给你哥哥。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/157.mp3`}),c[670]||=i(),c[671]||=a(`strong`,null,`Rachel Green:`,-1),c[672]||=i(` As I was saying… I should probably have the first of the three kids by the time I’m 35 which gives me five years. I love this plan! I wanna marry this plan!`,-1),c[673]||=a(`blockquote`,null,[a(`p`,null,`就像我刚才说的……我35岁的时候可能会有三个孩子中的第一个，这给了我五年的时间。我喜欢这个计划！我想和这个计划结婚！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/158.mp3`}),c[674]||=i(),c[675]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[676]||=i(` If you could do that, I’d marry the hippity-hop.`,-1),c[677]||=a(`blockquote`,null,[a(`p`,null,`如果你能做到的话，我会嫁给嬉皮士。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/159.mp3`}),c[678]||=i(),c[679]||=a(`strong`,null,`Rachel Green:`,-1),c[680]||=i(` So, if I wanna have my kid when I’m 35, I don’t have to get pregnant until I’m 34. Which gives Prada four years to start making maternity clothes! Oh wait, but I do want to be married for a year before I get pregnant…`,-1),c[681]||=a(`blockquote`,null,[a(`p`,null,`所以，如果我想在35岁时生下我的孩子，我不需要在34岁之前怀孕。这让普拉达有四年时间开始生产孕妇装！哦，等等，但我真的想在怀孕前结婚一年…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/160.mp3`}),c[682]||=i(),c[683]||=a(`strong`,null,`Monica Geller:`,-1),c[684]||=i(` Really! That long?! (Chandler slowly turns and looks at her.) (To Chandler) Look all you want, it’s happening!`,-1),c[685]||=a(`blockquote`,null,[a(`p`,null,`真的！那么长？！（钱德勒慢慢地转过身来看着她。）（对钱德勒）看看你想要的一切，一切都在发生！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/161.mp3`}),c[686]||=i(),c[687]||=a(`strong`,null,`Rachel Green:`,-1),c[688]||=i(` No, so I don’t have to get married until I’m 33! That’s three years, that’s three whole years—Oh, wait a minute though. I’ll need a year and a half to plan the wedding, and I’d like to know the guy for a year, year and a half before we get engaged… Which means I need to meet the guy by the time I’m thirty.`,-1),c[689]||=a(`blockquote`,null,[a(`p`,null,`不，所以我要到33岁才结婚！那是三年，那是整整三年哦，等等。我需要一年半的时间来计划婚礼，我想在订婚前认识那个男人一年半……这意味着我需要在三十岁之前认识那个男人。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/162.mp3`}),c[690]||=i(),c[691]||=a(`strong`,null,`Ross Geller:`,-1),c[692]||=i(` Which is fine! Because you just turned—(Removes two candles from the cake)—twenty-eight!`,-1),c[693]||=a(`blockquote`,null,[a(`p`,null,`那很好！因为你刚刚（从蛋糕上取下两支蜡烛）二十八！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/163.mp3`}),c[694]||=i(),c[695]||=a(`strong`,null,`Rachel Green:`,-1),c[696]||=i(` No! Ross, no! It is not fine! Eh-eh-according to my plan I should already be with the guy I wanna marry!`,-1),c[697]||=a(`blockquote`,null,[a(`p`,null,`不！罗斯，不！不好！呃，呃，根据我的计划，我应该已经和我想嫁的男人在一起了！`)],-1),c[698]||=a(`p`,null,[a(`em`,null,`(We hear Tag scream out in the hallway and jump into view of the open door on the scooter. He gives a hearty thumbs up to the group and rides off, with Joey following breathlessly behind.)`)],-1),c[699]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（我们听到塔格在走廊里尖叫，然后跳进摩托车上打开的门的视野。他向人群竖起大拇指，然后骑着车走了，乔伊气喘吁吁地跟在后面。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/164.mp3`}),c[700]||=t(` <strong>Joey Tribbiani:</strong> Will you quit hoggin’ it!<blockquote><p>你能不能别再胡闹了！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica’s birthday, Monica is now dressed and is being helped out by Chandler and Rachel.</em></p><blockquote><p>🎬 <em>莫妮卡的生日，莫妮卡现在穿好衣服，在钱德勒和瑞秋的帮助下。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E14/165.mp3`}),c[701]||=i(),c[702]||=a(`strong`,null,`Rachel Green:`,-1),c[703]||=i(` (To Chandler) I’m telling you it’s like watching Bambi learn how to walk.`,-1),c[704]||=a(`blockquote`,null,[a(`p`,null,`（对钱德勒）我告诉你，这就像看着斑比学会走路一样。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/166.mp3`}),c[705]||=i(),c[706]||=a(`strong`,null,`Ross Geller:`,-1),c[707]||=i(` (To Monica) You’re drunk! Mom and dad are gonna be maaaaadd! Maybe I’m a little drunk.`,-1),c[708]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）你喝醉了！妈妈和爸爸会很高兴的！也许我有点醉了。`)],-1),c[709]||=a(`p`,null,[a(`em`,null,`(Monica sits down on the barca lounger.)`)],-1),c[710]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡坐在巴萨躺椅上。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/167.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Chandler Bing:`,-1),c[713]||=i(` (to a waiter) Oh that’s great! Right there! Can we get some of that over here please? (The waiter comes over) There we go.`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`（对服务员）哦，太好了！就在那里！我们能在这里买一些吗？（服务员走过来）好了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/168.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[717]||=i(` (to the waiter) Hey! Are those crab cakes? (The waiter nods) Did I not tell ya to come straight to me when more crab cakes were ready?`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`（对服务员）嘿！那些是蟹肉蛋糕吗？（侍者点点头）我不是告诉你，等更多的蟹肉蛋糕准备好了，就直接来找我吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/169.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Chandler Bing:`,-1),c[721]||=i(` (To Monica) How are you feeling?`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）你感觉怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/170.mp3`}),c[723]||=i(),c[724]||=a(`strong`,null,`Monica Geller:`,-1),c[725]||=i(` You are so handsome! I wanna make love to you right here, right now! (Growls and pulls him into a kiss.)`,-1),c[726]||=a(`blockquote`,null,[a(`p`,null,`你真帅！我想现在就在这里和你做爱！（咆哮着，拉着他亲吻。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/171.mp3`}),c[727]||=i(),c[728]||=a(`strong`,null,`Ross Geller:`,-1),c[729]||=i(` I really wish that you wouldn’t.`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,`我真希望你不要。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/172.mp3`}),c[731]||=i(),c[732]||=a(`strong`,null,`Chandler Bing:`,-1),c[733]||=i(` (To Monica) Now all you have to do is just get through a little bit more, okay? Then we can put you in bed, okay? Just smile and don’t talk to anyone.`,-1),c[734]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）现在你所要做的就是多过一点，好吗？然后我们可以把你放在床上，好吗？只要微笑，不要和任何人说话。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/173.mp3`}),c[735]||=i(),c[736]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[737]||=i(` (clinking two glasses together) Speech! Speech! Let’s hear from the birthday girl! Huh?`,-1),c[738]||=a(`blockquote`,null,[a(`p`,null,`（碰碰两杯）讲话！演讲让我们听听生日女孩的话！嗯？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/174.mp3`}),c[739]||=i(),c[740]||=a(`strong`,null,`Chandler Bing:`,-1),c[741]||=i(` Pheebs!!`,-1),c[742]||=a(`blockquote`,null,[a(`p`,null,`菲比！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/175.mp3`}),c[743]||=i(),c[744]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[745]||=i(` Don’t you see? Everyone’s looking at me! The plan’s working! I didn’t even have to take off my top yet!`,-1),c[746]||=a(`blockquote`,null,[a(`p`,null,`你没看见吗？每个人都在看着我！计划成功了！我甚至还没脱掉上衣呢！`)],-1),c[747]||=a(`p`,null,`Mrs. Geller: Speech! Come on Monica!`,-1),c[748]||=a(`blockquote`,null,[a(`p`,null,`演讲！快点，莫妮卡！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/176.mp3`}),c[749]||=i(),c[750]||=a(`strong`,null,`Ross Geller:`,-1),c[751]||=i(` Come on!`,-1),c[752]||=a(`blockquote`,null,[a(`p`,null,`来吧！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/177.mp3`}),c[753]||=t(` <strong>All:</strong> Come on! Speech!<blockquote><p>来吧！演讲</p></blockquote><p><em>(Monica stands up and wobbles slightly and Chandler runs over to catch her.)</em></p><blockquote><p><em>（莫妮卡站起来，微微摇晃，钱德勒跑过去抓住她。）</em></p></blockquote><p>Mr. Geller: (filming this) Hey Chandler, you can’t keep your hands off her for one second!</p><blockquote><p>（拍摄这部电影）嘿，钱德勒，你的手一秒钟也离不开她！</p></blockquote><p>Mrs. Geller: Oh-ho, I think it’s nice.</p><blockquote><p>哦，我觉得很好。</p></blockquote>`,10),r(p,{src:`/audio/friends/S07/S07E14/178.mp3`}),c[754]||=i(),c[755]||=a(`strong`,null,`Chandler Bing:`,-1),c[756]||=i(` I think it’s necessary. (Backs away anyhow.)`,-1),c[757]||=a(`blockquote`,null,[a(`p`,null,`我认为这是必要的。（无论如何都要后退。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/179.mp3`}),c[758]||=i(),c[759]||=a(`strong`,null,`Monica Geller:`,-1),c[760]||=i(` I-I-I wanna thank you all for coming. My family and my friends…`,-1),c[761]||=a(`blockquote`,null,[a(`p`,null,`我，我，我要感谢你们所有人的到来。我的家人和朋友…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/180.mp3`}),c[762]||=i(),c[763]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[764]||=i(` (screaming) Wooo!! Hoo!!`,-1),c[765]||=a(`blockquote`,null,[a(`p`,null,`（尖叫）哇！！呼！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/181.mp3`}),c[766]||=i(),c[767]||=a(`strong`,null,`Monica Geller:`,-1),c[768]||=i(` I really like to say that I’m-um… (Pause) Y’know what I’d really like to say? I’m drunk!! (Mrs. Geller pulls the camera down.) That’s right mom and dad your little Harmonica is hammered!! (Ross grabs the camera out of his dad’s hands.) And guess what! I’ve been drunk before! And I’ve smoked a cigarette! And I got a box of Ding-Dongs hidden in my underwear drawer! It’s all okay. It’s okay because I turned thirty today. And, and I can do anything I want! Because I am a grown up. (Falls over sideways with Ross filming the fall.)`,-1),c[769]||=a(`blockquote`,null,[a(`p`,null,`我真的很想说我…（停顿）你知道我真的想说什么吗？我喝醉了！！（盖勒太太把相机拉下来。）对了，爸爸妈妈，你的小口琴被锤打了！！（罗斯从他爸爸手里抓起相机。）猜猜怎么着！我以前喝醉过！我还抽了一支烟！我的内衣抽屉里藏了一盒叮当！没关系。没关系，因为我今天三十岁了。而且，我可以做任何我想做的事！因为我已经长大了。（在罗斯拍摄瀑布的过程中侧身倒下。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/182.mp3`}),c[770]||=i(),c[771]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[772]||=i(` (To Joey) Okay quick, help me get this off! (Motions to her top.)`,-1),c[773]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）好的，快，帮我把这个拿下来！（向她的头顶示意。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/183.mp3`}),c[774]||=t(` <strong>Joey Tribbiani:</strong> Yeah!!<blockquote><p>是的！！</p></blockquote><p><em>(Ross pans the camera over to Phoebe.)</em></p><blockquote><p><em>（罗斯将摄像机移到菲比身上。）</em></p></blockquote><hr><p>🎬 <em>Phoebe’s birthday, she’s telling everyone what she found out at Ursula’s while sitting in Central Perk.</em></p><blockquote><p>🎬 <em>菲比的生日，她告诉大家她坐在中央公园时在乌苏拉家发现的一切。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E14/184.mp3`}),c[775]||=i(),c[776]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[777]||=i(` I lost a whole year! I can’t believe it! This is so unfair!`,-1),c[778]||=a(`blockquote`,null,[a(`p`,null,`我输了整整一年！真不敢相信！这太不公平了！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/185.mp3`}),c[779]||=i(),c[780]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[781]||=i(` Oh, I don’t know Pheebs. It’ll be okay.`,-1),c[782]||=a(`blockquote`,null,[a(`p`,null,`哦，我不认识菲比。没事的。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/186.mp3`}),c[783]||=i(),c[784]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[785]||=i(` Will it? Will it?! I mean, how would you feel if you found out you were 31?`,-1),c[786]||=a(`blockquote`,null,[a(`p`,null,`会吗？会吗？！我是说，如果你发现自己31岁，你会有什么感觉？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/187.mp3`}),c[787]||=i(),c[788]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[789]||=i(` That’s not gonna happen. No. (Looks up) Because we have a new deal!`,-1),c[790]||=a(`blockquote`,null,[a(`p`,null,`那不会发生的。不，（抬头）因为我们有新的交易！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/188.mp3`}),c[791]||=i(),c[792]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[793]||=i(` Plus, it totally ruined my schedule! I…I haven’t done any of the things I wanted to do by the time I was 31!`,-1),c[794]||=a(`blockquote`,null,[a(`p`,null,`而且，它完全破坏了我的日程安排！到31岁的时候，我还没有做任何我想做的事情！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/189.mp3`}),c[795]||=i(),c[796]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[797]||=i(` Like what?`,-1),c[798]||=a(`blockquote`,null,[a(`p`,null,`像什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/190.mp3`}),c[799]||=i(),c[800]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[801]||=i(` Like okay I-I-I, I haven’t met any Portuguese people! I, I haven’t had the perfect kiss! And I haven’t been to sniper’s school!`,-1),c[802]||=a(`blockquote`,null,[a(`p`,null,`好吧，我，我，我还没见过葡萄牙人！一、 我还没有得到完美的吻！我还没去过狙击手学校！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/191.mp3`}),c[803]||=i(),c[804]||=a(`strong`,null,`Monica Geller:`,-1),c[805]||=i(` Phoebe, y’know why don’t we just go upstairs and have some birthday cake?`,-1),c[806]||=a(`blockquote`,null,[a(`p`,null,`菲比，你知道我们为什么不上楼吃点生日蛋糕呢？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/192.mp3`}),c[807]||=i(),c[808]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[809]||=i(` No, I just feel like being by myself for a while. All right? I’ll see you guys later. Thanks. (Gets up and exits.)`,-1),c[810]||=a(`blockquote`,null,[a(`p`,null,`不，我只是想一个人呆一会儿。好吧待会儿见。谢谢（起身离开。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/193.mp3`}),c[811]||=i(),c[812]||=a(`strong`,null,`Rachel Green:`,-1),c[813]||=i(` Hey. (After she leaves.) Oh, poor Pheebs.`,-1),c[814]||=a(`blockquote`,null,[a(`p`,null,`嘿。（在她离开后）哦，可怜的菲比。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/194.mp3`}),c[815]||=i(),c[816]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[817]||=i(` Hey, y’know what you guys? I think I’m gonna go walk her home. (Gets up and runs out.)`,-1),c[818]||=a(`blockquote`,null,[a(`p`,null,`嘿，你们知道吗？我想我要送她回家。（站起来跑了出去。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/195.mp3`}),c[819]||=i(),c[820]||=a(`strong`,null,`Monica Geller:`,-1),c[821]||=i(` Oh man!`,-1),c[822]||=a(`blockquote`,null,[a(`p`,null,`哦，老兄！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/196.mp3`}),c[823]||=i(),c[824]||=a(`strong`,null,`Chandler Bing:`,-1),c[825]||=i(` What?`,-1),c[826]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/197.mp3`}),c[827]||=i(),c[828]||=a(`strong`,null,`Monica Geller:`,-1),c[829]||=i(` He’s gonna eat the cake!`,-1),c[830]||=a(`blockquote`,null,[a(`p`,null,`他会吃蛋糕的！`)],-1),c[831]||=a(`p`,null,`[Cut outside, Joey is catching up with Phoebe.]`,-1),c[832]||=a(`blockquote`,null,[a(`p`,null,`[切到外面，乔伊正赶上菲比。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/198.mp3`}),c[833]||=i(),c[834]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[835]||=i(` Pheebs! Wait up! (She stops.) Listen uh, close your eyes. (She does so and Joey passionately kisses her.) Maybe that’s one thing you can cross off your list.`,-1),c[836]||=a(`blockquote`,null,[a(`p`,null,`菲比！等等！（她停下来）听着，呃，闭上眼睛。（她这么做了，乔伊热情地吻了她。）也许这是一件你可以从清单上划掉的事情。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/199.mp3`}),c[837]||=i(),c[838]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[839]||=i(` Oh yeah.`,-1),c[840]||=a(`blockquote`,null,[a(`p`,null,`哦，是的。`)],-1),c[841]||=a(`p`,null,[a(`em`,null,`(Joey starts to walk away, but stops.)`)],-1),c[842]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊开始走开，但停了下来。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/200.mp3`}),c[843]||=i(),c[844]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[845]||=i(` Oh, and plus I’m 1/16th Portuguese.`,-1),c[846]||=a(`blockquote`,null,[a(`p`,null,`哦，而且我是1/16葡萄牙人。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/201.mp3`}),c[847]||=i(),c[848]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[849]||=i(` Oh! (Phoebe walks away smiling.)`,-1),c[850]||=a(`blockquote`,null,[a(`p`,null,`哦！（菲比笑着走开了。）`)],-1),c[851]||=a(`hr`,null,null,-1),c[852]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross’s birthday, his car is still trapped in it’s spot. Now Joey, Phoebe, and Ross are at the front of the car with Monica, Rachel, and Chandler at the rear of the car.`)],-1),c[853]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯的生日，他的车仍被困在原地。现在乔伊、菲比和罗斯在车的前部，莫妮卡、瑞秋和钱德勒在车的后部。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/202.mp3`}),c[854]||=i(),c[855]||=a(`strong`,null,`Ross Geller:`,-1),c[856]||=i(` Okay, is everybody clear? We’re gonna pick it up…and move it. Now all we need is teamwork, okay? We’re gonna lift the car…and slide it out. Lift and slide!`,-1),c[857]||=a(`blockquote`,null,[a(`p`,null,`好的，大家都清楚了吗？我们要把它捡起来…然后移动它。现在我们只需要团队合作，好吗？我们要把车抬起来…然后把它滑出来。抬起并滑动！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/203.mp3`}),c[858]||=i(),c[859]||=a(`strong`,null,`Rachel Green:`,-1),c[860]||=i(` Ross, I really don’t think…`,-1),c[861]||=a(`blockquote`,null,[a(`p`,null,`罗斯，我真的不认为…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/204.mp3`}),c[862]||=i(),c[863]||=a(`strong`,null,`Ross Geller:`,-1),c[864]||=i(` (interrupting her) Lift!! And slide!`,-1),c[865]||=a(`blockquote`,null,[a(`p`,null,`（打断她）电梯！！然后滑！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/205.mp3`}),c[866]||=i(),c[867]||=a(`strong`,null,`Chandler Bing:`,-1),c[868]||=i(` Okay, here we go.`,-1),c[869]||=a(`blockquote`,null,[a(`p`,null,`好了，开始吧。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/206.mp3`}),c[870]||=i(),c[871]||=a(`strong`,null,`Ross Geller:`,-1),c[872]||=i(` All right everyone, lift! (They and try to lift the car, of course it doesn’t raise up) And slide!! (Everyone leans over, but the car still does not move.)`,-1),c[873]||=a(`blockquote`,null,[a(`p`,null,`好了，各位，举起来！（他们试着把车抬起来，当然不会抬起来）然后滑动！！（每个人都倾过身来，但车还是一动不动。）`)],-1),c[874]||=a(`hr`,null,null,-1),c[875]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Rachel’s birthday, she is coming into the hallway where Joey and Tag are playing with the scooter.`)],-1),c[876]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`瑞秋的生日，她走进走廊，乔伊和泰格正在玩滑板车。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/207.mp3`}),c[877]||=i(),c[878]||=a(`strong`,null,`Rachel Green:`,-1),c[879]||=i(` Hey Joey, can I…`,-1),c[880]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔伊，我能…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/208.mp3`}),c[881]||=i(),c[882]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[883]||=i(` Oh, come on Rach! My turn just started!`,-1),c[884]||=a(`blockquote`,null,[a(`p`,null,`噢，来吧，瑞秋！轮到我了！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/209.mp3`}),c[885]||=i(),c[886]||=a(`strong`,null,`Rachel Green:`,-1),c[887]||=i(` Actually, I just wanna talk to Tag.`,-1),c[888]||=a(`blockquote`,null,[a(`p`,null,`事实上，我只是想和泰格谈谈。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/210.mp3`}),c[889]||=i(),c[890]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[891]||=i(` Oh. Okay. Hey, can I ride this outside?`,-1),c[892]||=a(`blockquote`,null,[a(`p`,null,`哦。可以嘿，我能在外面骑吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/211.mp3`}),c[893]||=i(),c[894]||=a(`strong`,null,`Rachel Green:`,-1),c[895]||=i(` Whatever! Okay, I’m not your mother.`,-1),c[896]||=a(`blockquote`,null,[a(`p`,null,`不管怎样！好吧，我不是你妈妈。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/212.mp3`}),c[897]||=i(),c[898]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[899]||=i(` Okay! (Runs off downstairs.)`,-1),c[900]||=a(`blockquote`,null,[a(`p`,null,`好的！（跑向楼下。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/213.mp3`}),c[901]||=i(),c[902]||=a(`strong`,null,`Rachel Green:`,-1),c[903]||=i(` Not in the street!!`,-1),c[904]||=a(`blockquote`,null,[a(`p`,null,`不是在街上！！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/214.mp3`}),c[905]||=i(),c[906]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[907]||=i(` Yes!`,-1),c[908]||=a(`blockquote`,null,[a(`p`,null,`是的！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/215.mp3`}),c[909]||=i(),c[910]||=a(`strong`,null,`Rachel Green:`,-1),c[911]||=i(` (to Tag) Hi.`,-1),c[912]||=a(`blockquote`,null,[a(`p`,null,`（对Tag）嗨。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/216.mp3`}),c[913]||=i(),c[914]||=a(`strong`,null,`Tag:`,-1),c[915]||=i(` Hey.`,-1),c[916]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/217.mp3`}),c[917]||=i(),c[918]||=a(`strong`,null,`Rachel Green:`,-1),c[919]||=i(` Hey.`,-1),c[920]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/218.mp3`}),c[921]||=i(),c[922]||=a(`strong`,null,`Tag:`,-1),c[923]||=i(` How are you doing? Are you feeling any better?`,-1),c[924]||=a(`blockquote`,null,[a(`p`,null,`你好吗？你感觉好些了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/219.mp3`}),c[925]||=i(),c[926]||=a(`strong`,null,`Rachel Green:`,-1),c[927]||=i(` Yeah, I’m doing okay. I’m um…let’s talk.`,-1),c[928]||=a(`blockquote`,null,[a(`p`,null,`是的，我很好。我…我们谈谈。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/220.mp3`}),c[929]||=i(),c[930]||=a(`strong`,null,`Tag:`,-1),c[931]||=i(` Okay. (They sit on the step.)`,-1),c[932]||=a(`blockquote`,null,[a(`p`,null,`好的。（他们坐在台阶上。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/221.mp3`}),c[933]||=i(),c[934]||=a(`strong`,null,`Rachel Green:`,-1),c[935]||=i(` Umm…`,-1),c[936]||=a(`blockquote`,null,[a(`p`,null,`嗯…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/222.mp3`}),c[937]||=i(),c[938]||=a(`strong`,null,`Tag:`,-1),c[939]||=i(` What’s up?`,-1),c[940]||=a(`blockquote`,null,[a(`p`,null,`怎么了？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/223.mp3`}),c[941]||=i(),c[942]||=a(`strong`,null,`Rachel Green:`,-1),c[943]||=i(` Ohh Tag, umm…you’re such a great guy and we have sooo much fun together but I don’t-I don’t…`,-1),c[944]||=a(`blockquote`,null,[a(`p`,null,`哦，塔格，嗯……你是个很棒的家伙，我们在一起很开心，但我不，我不…`)],-1),r(p,{src:`/audio/friends/S07/S07E14/224.mp3`}),c[945]||=i(),c[946]||=a(`strong`,null,`Tag:`,-1),c[947]||=i(` Wait! I think I see where you’re going, but before you say anything else, can I just say one more thing? (Kisses her.)`,-1),c[948]||=a(`blockquote`,null,[a(`p`,null,`等等！我想我知道你要去哪里了，但在你说别的之前，我能再说一件事吗？（吻她。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/225.mp3`}),c[949]||=i(),c[950]||=a(`strong`,null,`Rachel Green:`,-1),c[951]||=i(` Well said. And a uh good example of the fun I was referring to uhh, but I just think I’m past the point where I think I can y’know, just have fun.`,-1),c[952]||=a(`blockquote`,null,[a(`p`,null,`说得好。这是一个很好的例子，我指的是乐趣，但我只是觉得我已经过了我认为我可以享受乐趣的阶段。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/226.mp3`}),c[953]||=i(),c[954]||=a(`strong`,null,`Tag:`,-1),c[955]||=i(` Rachel, don’t do this. This is just because you’re turning thirty.`,-1),c[956]||=a(`blockquote`,null,[a(`p`,null,`瑞秋，别这样。这只是因为你快三十岁了。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/227.mp3`}),c[957]||=i(),c[958]||=a(`strong`,null,`Rachel Green:`,-1),c[959]||=i(` Yeah, it is! But you’re just a kid! I mean you’re 25!`,-1),c[960]||=a(`blockquote`,null,[a(`p`,null,`是的，是的！但你只是个孩子！我是说你25岁了！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/228.mp3`}),c[961]||=i(),c[962]||=a(`strong`,null,`Tag:`,-1),c[963]||=i(` Twenty-four actually.`,-1),c[964]||=a(`blockquote`,null,[a(`p`,null,`实际上是二十四。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/229.mp3`}),c[965]||=i(),c[966]||=a(`strong`,null,`Rachel Green:`,-1),c[967]||=i(` Oh God! Y’know what I wish? I wish you were six years older. Well actually, if I’m wishin’ for stuff, I actually wish I was six years younger.`,-1),c[968]||=a(`blockquote`,null,[a(`p`,null,`哦，上帝！你知道我想要什么吗？我希望你大六岁。嗯，事实上，如果我想得到一些东西，我真希望自己能年轻六岁。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/230.mp3`}),c[969]||=i(),c[970]||=a(`strong`,null,`Tag:`,-1),c[971]||=i(` Me too.`,-1),c[972]||=a(`blockquote`,null,[a(`p`,null,`我也是。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/231.mp3`}),c[973]||=i(),c[974]||=a(`strong`,null,`Rachel Green:`,-1),c[975]||=i(` Yeah, I’m sorry. (They hug.)`,-1),c[976]||=a(`blockquote`,null,[a(`p`,null,`是的，对不起。（他们拥抱。）`)],-1),c[977]||=a(`p`,null,[i(`⏱ `),a(`em`,null,`Time lapse, Rachel is entering her apartment after breaking up with Tag.`)],-1),c[978]||=a(`blockquote`,null,[a(`p`,null,`[时间流逝，Rachel在与Tag分手后进入她的公寓。]`)],-1),r(p,{src:`/audio/friends/S07/S07E14/232.mp3`}),c[979]||=i(),c[980]||=a(`strong`,null,`Chandler Bing:`,-1),c[981]||=i(` Hey! How’d it go?`,-1),c[982]||=a(`blockquote`,null,[a(`p`,null,`嘿！进展如何？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/233.mp3`}),c[983]||=i(),c[984]||=a(`strong`,null,`Rachel Green:`,-1),c[985]||=i(` Oh, if I only want two kids, can I keep him for another year?`,-1),c[986]||=a(`blockquote`,null,[a(`p`,null,`噢，如果我只想要两个孩子，我能再养他一年吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/234.mp3`}),c[987]||=i(),c[988]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[989]||=i(` You did the right thing.`,-1),c[990]||=a(`blockquote`,null,[a(`p`,null,`你做得对。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/235.mp3`}),c[991]||=i(),c[992]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[993]||=i(` (entering, limping, and holding his arm) I don’t like this anymore. (He sits down with them in pain.)`,-1),c[994]||=a(`blockquote`,null,[a(`p`,null,`（进来，一瘸一拐地，抱着他的胳膊）我再也不喜欢这样了。（他痛苦地和他们坐在一起。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/236.mp3`}),c[995]||=i(),c[996]||=a(`strong`,null,`Chandler Bing:`,-1),c[997]||=i(` Well, here we are, just a bunch of thirty year olds.`,-1),c[998]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们到了，只是一群三十岁的孩子。`)],-1),r(p,{src:`/audio/friends/S07/S07E14/237.mp3`}),c[999]||=i(),c[1e3]||=a(`strong`,null,`Ross Geller:`,-1),c[1001]||=i(` God, do you realize in ten years we’re gonna be 40?`,-1),c[1002]||=a(`blockquote`,null,[a(`p`,null,`天啊，你意识到十年后我们就要40岁了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/238.mp3`}),c[1003]||=i(),c[1004]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1005]||=i(` (crying) Why God?! Why are you doing this to us?! (He buries his head in Ross’s shoulder.)`,-1),c[1006]||=a(`blockquote`,null,[a(`p`,null,`（哭）为什么是上帝？！你为什么这样对我们？！（他把头埋在罗斯的肩膀上。）`)],-1),c[1007]||=a(`hr`,null,null,-1),c[1008]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross’s birthday, night has fallen and Joey and Ross are walking by where his car is parked to find that both cars blocking him in have left.`)],-1),c[1009]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯的生日，夜幕降临，乔伊和罗斯走过他的车停的地方，发现挡住他的两辆车都走了。`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/239.mp3`}),c[1010]||=i(),c[1011]||=a(`strong`,null,`Ross Geller:`,-1),c[1012]||=i(` Yes! My baby’s finally free!`,-1),c[1013]||=a(`blockquote`,null,[a(`p`,null,`是的！我的孩子终于自由了！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/240.mp3`}),c[1014]||=i(),c[1015]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1016]||=i(` All-all right! (They run and jump in the car.) Start it up! Let’s go!`,-1),c[1017]||=a(`blockquote`,null,[a(`p`,null,`好吧！（他们在车里跑来跑去）发动起来！走吧！`)],-1),r(p,{src:`/audio/friends/S07/S07E14/241.mp3`}),c[1018]||=i(),c[1019]||=a(`strong`,null,`Ross Geller:`,-1),c[1020]||=i(` (starting it) Woohoo!`,-1),c[1021]||=a(`blockquote`,null,[a(`p`,null,`（开始）呜呼！`)],-1),c[1022]||=a(`p`,null,[a(`em`,null,`(Just as they are about to pull away, a big, fat, bald guy pulls up in the exact same car as Ross and stops next to him.)`)],-1),c[1023]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（就在他们要离开的时候，一个又大又胖的秃头家伙停在了罗斯的同一辆车里，停在他旁边。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E14/242.mp3`}),c[1024]||=i(),c[1025]||=a(`strong`,null,`The Man In The Sportscar:`,-1),c[1026]||=i(` How hot are we? (He drives off.)`,-1),c[1027]||=a(`blockquote`,null,[a(`p`,null,`我们有多热？（他开车走了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E14/243.mp3`}),c[1028]||=i(),c[1029]||=a(`strong`,null,`Ross Geller:`,-1),c[1030]||=i(` You wanna buy a car?`,-1),c[1031]||=a(`blockquote`,null,[a(`p`,null,`你想买辆车吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E14/244.mp3`}),c[1032]||=t(` <strong>Joey Tribbiani:</strong> No.<blockquote><p>没有。</p></blockquote><p><em>(Ross shuts it off and they get out.)</em></p><blockquote><p><em>（罗斯关上电源，他们就出来了。）</em></p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><p>{Transcriber’s Note: There was no credits scene with this episode.}</p><blockquote><p>{抄写者注：这一集没有字幕场景。}</p></blockquote>`,10)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};